using namespace std;

vector<int> buildSequence(int n, int delta, const vector<int>& c) {
    vector<int> x;
    x.push_back(c[0]);

    for (int i = 1; i < n; i++) {
        // 直接接在后面可以被保留
        if ((long long)c[i - 1] + delta <= c[i]) {
            x.push_back(c[i]);
        } else {
            // 插入字典序最小的正整数 1
            x.push_back(1);
            x.push_back(c[i]);
        }
    }

    return x;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int t;
    cin >> t;

    while (t--) {
        int n, delta;
        cin >> n >> delta;

        vector<int> c(n);
        for (int i = 0; i < n; i++) {
            cin >> c[i];
        }

        vector<int> x = buildSequence(n, delta, c);

        cout << x.size() << '\n';
        for (int i = 0; i < (int)x.size(); i++) {
            if (i > 0) cout << ' ';
            cout << x[i];
        }
        cout << '\n';
    }

    return 0;
